examples:
#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    int n, k;
    if (!(std::cin >> n >> k)) { return 1; }
    std::vector<int> a;
    int value;
    while (std::cin >> value) { a.push_back(value); }
    int low = 0;
    int high = 0;
    for (int i = 0; i < n; i++) {
        low = std::max(low, a[i]);
        high += a[i];
    }
    while (low < high) {
        int middle = low + (high - low) / 2;
        int groups = 1;
        int load = 0;
        for (int i = 0; i < n; i++) {
            if (load + a[i] > middle) {
                groups++;
                load = 0;
            }
            load += a[i];
        }
        if (groups <= k) {
            high = middle;
        } else {
            low = middle + 1;
        }
    }
    std::cout << low << "\n";
    return 0;
}

