sections.code:
#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    int n, k;
    if (!(std::cin >> n >> k)) { return 1; }
    std::vector<int> a;
    int value;
    while (std::cin >> value) { a.push_back(value); }
    std::vector<int> dp(k + 1, 1000000);
    dp[0] = 0;
    for (int amount = 1; amount <= k; amount++) {
        for (int i = 0; i < n; i++) {
            if (a[i] <= amount) {
                dp[amount] = std::min(dp[amount], dp[amount - a[i]] + 1);
            }
        }
    }
    int answer = dp[k];
    if (answer >= 1000000) {
        answer = -1;
    }
    std::cout << answer << "\n";
    return 0;
}

