    dp[0] = 0;
    for (int amount = 1; amount <= k; amount++) {
        for (int i = 0; i < n; i++) {
            if (a[i] <= amount) {
                dp[amount] = std::min(dp[amount], dp[amount - a[i]] + 1);
            }
        }
    }
    int answer = dp[k];
    if (answer >= 1000000) {
        answer = -1;
    }
    std::cout << answer << "\n";
    return 0;
}

