import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt(); int[] values = new int[n]; for (int i = 0; i < n; i++) values[i] = scanner.nextInt();
        int answer = values[0]; for (int i = 1; i < n; i++) if (values[i] > answer) answer = values[i]; System.out.println(answer);
    }
}

