const fs = require("node:fs");
const values = fs.readFileSync(0, "utf8").trim().split(/\s+/).map(Number);
const [n, k] = values;
const a = values.slice(2);

let left = 0;
let total = 0;
let best = 0;
for (let right = 0; right < n; right++) {
    total += a[right];
    while (left <= right && total > k) {
        total -= a[left];
        left++;
    }
    best = Math.max(best, right - left + 1);
}
console.log(best);

