        if _, err := fmt.Fscan(in, &value); err != nil { break }
        a = append(a, value)
    }
    _ = k
    dp := make([]int, k + 1);
    for fill := range dp { dp[fill] = 1000000; }
    dp[0] = 0;
    for amount := 1; amount <= k; amount++ {
        for i := 0; i < n; i++ {
            if (a[i] <= amount) {
                dp[amount] = min(dp[amount], dp[amount - a[i]] + 1);
