    "os"
)

func main() {
    in := bufio.NewReader(os.Stdin)
    out := bufio.NewWriter(os.Stdout)
    defer out.Flush()
    var n, k int
    if _, err := fmt.Fscan(in, &n, &k); err != nil { return }
    a := []int{}
    for {
        var value int
        if _, err := fmt.Fscan(in, &value); err != nil { break }
        a = append(a, value)
    }
    _ = k
    distance := make([]int, n);
    for fill := range distance { distance[fill] = -1; }
    queue := make([]int, n);
    for fill := range queue { queue[fill] = 0; }
    head := 0;
    tail := 0;
    distance[k] = 0;
    queue[tail] = k;
    tail++;
    for (head < tail) {
        vertex := queue[head];
        head++;
        for next := 0; next < n; next++ {
            if (a[vertex * n + next] != 0 && distance[next] == -1) {
                distance[next] = distance[vertex] + 1;
                queue[tail] = next;
                tail++;
            }
        }
    }
    for i := 0; i < n; i++ {
        fmt.Fprintln(out, distance[i]);
    }
}

